row.update({f'choice{i+1}':v for i,v in enumerate(q['choices'])})
with (root/'public/templates/questions.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(row),lineterminator='\n');w.writeheader();w.writerow(row)
